import { Router } from "express";
import { z } from "zod";
import * as messageController from "../controllers/message.controller.js";
import { authenticate } from "../middleware/auth.js";
import { validate } from "../middleware/validate.js";
import { cloudinaryUrl } from "../utils/validators.js";
import { MAX_MESSAGE_LENGTH } from "../services/message.service.js";

const router = Router();

// Zod schemas for message payloads
// SYSTEM messages ("X added Y") are generated by the server only — letting clients
// send them would allow anyone to forge group announcements.
const sendMessageSchema = z.object({
  content: z.string().max(MAX_MESSAGE_LENGTH).optional().nullable(),
  type: z.enum(["TEXT", "IMAGE", "VIDEO", "AUDIO", "FILE"]).default("TEXT"),
  attachments: z
    .array(
      z.object({
        fileName: z.string().min(1).max(255),
        fileType: z.string().max(20),
        fileSize: z.number().int().nonnegative(),
        fileUrl: cloudinaryUrl,
        mimeType: z.string().max(127),
      })
    )
    .max(10)
    .optional(),
});

const deleteMessageSchema = z.object({
  scope: z.enum(["me", "everyone"]),
});

// All message routes require authentication
router.use(authenticate);

// Chat specific endpoints
router.post("/:chatId", validate(sendMessageSchema), messageController.sendNewMessage);
router.get("/:chatId", messageController.fetchChatMessages);
router.delete("/:chatId/:messageId", validate(deleteMessageSchema), messageController.deleteChatMessage);

export default router;
